func (c *Controller) getRegistrationMethod(podInfo *PodInfo) RegistrationMethod {
	ns := podInfo.Namespace
	excludedNamespaces := os.Getenv(utils.ExcludeNamespacesKey)
	namespaces := make([]string, 0)
	if excludedNamespaces != "" {
		namespaces = strings.Split(excludedNamespaces, ",")
	}
	namespaces = append(namespaces, utils.DefaultExcludedNamespaces...)
	for _, ens := range namespaces {
		regex, err := regexp.Compile(strings.TrimSpace(ens))
		if err != nil {
			continue
		}
		if regex.MatchString(ns) {
			return ""
		}
	}

	// Check for nexus annotation
	if value, ok := podInfo.Annotations[utils.NexusRegisterEnabledAnnotation]; ok {
		enabled, err := strconv.ParseBool(value)
		if err != nil || !enabled {
			return ""
		}
		return RegistrationMethodAnnotation
	}

	// Check for legacy consul annotation
	if value, ok := podInfo.Annotations[utils.LegacyConsulRegisterEnabledAnnotation]; ok {
		enabled, err := strconv.ParseBool(value)
		if err != nil || !enabled {
			return ""
		}
		return RegistrationMethodAnnotation
	}

	// Check if namespace is labeled for registration
	nsMap := *c.namespaces.Load()
	if nsMap[podInfo.Namespace] {
		svcs := *c.k8sServices.Load()
		if isPodPartOfK8sService(podInfo, svcs) {
			return RegistrationMethodK8sService
		}
		return ""
	}

	// Check global cluster registration
	if global.IsClusterRegistrationEnabled() {
		svcs := *c.k8sServices.Load()
		if isPodPartOfK8sService(podInfo, svcs) {
			return RegistrationMethodK8sService
		}
		return RegistrationMethodNamespace
	}

	return ""
}

func findK8sServiceName(pod *PodInfo, k8sServices map[string]core.Service) []string {
	foundServices := make([]string, 0)
	for _, svc := range k8sServices {
		selector := svc.Spec.Selector
		matches := true

		if len(selector) == 0 || pod.Namespace != svc.Namespace {
			continue
		}

		// Check if all selector labels match the pod labels
		for key, value := range selector {
			if pod.Labels[key] != value {
				matches = false
				break
			}
		}

		if matches {
			foundServices = append(foundServices, svc.Name)
		}
	}

	return foundServices
}

